import { Component, EventEmitter, HostBinding, Input, OnChanges, OnInit, Output, SimpleChanges, ViewEncapsulation } from '@angular/core';
import { MatIconModule } from '@angular/material/icon';
import { BooleanInput, coerceBooleanProperty } from '@angular/cdk/coercion';
import { NgForOf, NgIf } from '@angular/common';

export type DscAlertVariant = 'success' | 'danger' | 'warning' | 'info';

@Component({
  selector: 'dsc-alert',
  standalone: true,
  imports: [MatIconModule, NgIf, NgForOf],
  templateUrl: './dsc-alert.component.html',
  styleUrls: ['./dsc-alert.component.scss'],
  encapsulation: ViewEncapsulation.None
})
export class DscAlertComponent implements OnInit, OnChanges {

  @Input()
  title?: string;

  @Input()
  get message() {
    return this._message;
  }

  set message(valor: string) {
    this._message = valor;
  }

  _message: string = '';

  @Input()
  get list() {
    return this._list;
  }

  set list(values: string[]) {
    this._list = values;
  }

  _list: string[] = [];

  @Input()
  get showIcon(): boolean {
    return this._showIcon;
  }

  set showIcon(value: BooleanInput) {
    this._showIcon = coerceBooleanProperty(value);
  }

  private _showIcon = false;

  @Input()
  get dismissible(): boolean {
    return this._dismissible;
  }

  set dismissible(value: BooleanInput) {
    this._dismissible = coerceBooleanProperty(value);
  }

  private _dismissible = false;

  @Input()
  get variant(): DscAlertVariant {
    return this._variant;
  }

  set variant(variant: DscAlertVariant) {
    this._variant = variant;
    this.matIconName = variant;
  }

  @Input() headingLevelTitle?: string;

  _variant: DscAlertVariant = 'info';

  @Output() linkFunction = new EventEmitter<void>();

  @HostBinding('style.display')

  display = 'block';

  ngOnInit(): void {
    this.validateMessage();
  }

  ngOnChanges(): void {
    this.validateMessage();
  }

  get matIconName(): string {
    return this._matIconName;
  }

  set matIconName(value: string) {
    switch (value) {
      case 'info':
        this._matIconName = 'info';
        break;
      case 'danger':
        this._matIconName = 'error';
        break;
      case 'success':
        this._matIconName = 'check_circle';
        break;
      case 'warning':
        this._matIconName = 'warning';
        break;
    }
  }

  _matIconName: string = 'info';

  classes = '';

  get ariaLabel(): string {
    switch (this.variant) {
      case 'info':
        return 'Informação';
      case 'danger':
        return 'Perigo';
      case 'success':
        return 'Sucesso';
      case 'warning':
        return 'Aviso';
    }
  }

  handleClick(event: Event) {
    const target = event.target as HTMLElement;

    if (target.tagName === 'A' && target.classList.contains('custom-link')) {
      event.preventDefault();
      this.linkFunction.emit();
    }
  }

  
  private getHeadingTag(level?: string): string {
    const valid = ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'];
    return valid.includes(level || '') ? level! : 'h3';
  }

  private validateMessage() {
    if (!this.message && !this.list?.length) {
      this.display = 'none';
      console.warn("DSC-ALERT: É obrigatório o uso de 'message' ou de 'list'. O atributo não foi enviado.");
    } else {
      this.display = 'block';
    }
  }

  getTitleHtml(): string {
    if (!this.title) return '';
    const tag = this.getHeadingTag(this.headingLevelTitle);
    const ariaLevel = tag.startsWith('h') ? tag.replace('h', '') : '';
    return `<${tag} class="dsc-alert-content__title" role="heading" aria-level="${ariaLevel}">
              ${this.title}
            </${tag}>`;
  }

}
